BEGIN;
UPDATE public.questions SET explanation_data = explanation_data || '{"kid": "AIは「どれだけ間違えたか」の情報を、答えの出口から入口へ順番に伝えて、各層のつまみ（重み）を少しずつ直しながら賢くなる。ところがシグモイドという部品を通るたびに、その「直してね」という合図が必ず小さくされてしまう。層が深いと“小さくする”が何度も重なり、合図がほぼ消えて入口に近い層まで届かない。すると手前の層は直しようがなく、学習が進まない。これが勾配消失。", "eg": "伝言ゲームで、後ろに伝わるほど声が小さくなり、最後の人には何も聞こえない。手前の層に、学習の「直してね」という声が届かないのと同じ。", "think": "学習の「直してね」の合図は、層を1つ通るたびシグモイドで縮められる。シグモイドは一番効くところでも合図を4分の1以下にしてしまうので、層が深いほど縮小が積み重なって消えていく。合図をあまり縮めないReLUに替えると和らぐ。", "point": "学習の「直してね」の合図が、深い層を伝わるうちに小さくなって消える。これが勾配消失。"}'::jsonb WHERE source_ref = 'g-kentei-q18' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || '{"kid": "AIは答えのズレ（間違いの大きさ）を、出口の層から入口の層へ順番にさかのぼらせて、「どのつまみ（重み）を、どちらへ、どれだけ回せば正解に近づくか」をまとめて計算する。この仕組みがあるからニューラルネットは学べる。だから“学習の心臓”と呼ばれる。"}'::jsonb WHERE source_ref = 'g-kentei-q21' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || '{"kid": "AIの学習は「成績が一番良くなる場所へ、少しずつ坂を下っていく」イメージ。その下り方を賢くするのが最適化で、Adamは「これまで進んできた勢いを活かす工夫（モメンタム）」と「方向ごとに歩幅を自動で変える工夫（RMSProp）」の合わせ技。"}'::jsonb WHERE source_ref = 'g-kentei-q20' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || '{"kid": "モデルは項目ごとに「効き具合のつまみ（重み）」を持っている。L1は、そのうち要らないつまみを「スパッと0」にして、効く項目だけを残す（＝項目のえり分け）。L2は全部のつまみを「なだらかに小さく」するだけで、ちょうど0にはしにくい。"}'::jsonb WHERE source_ref = 'g-kentei-q22' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
COMMIT;
